//! 偏離路線偵測與導引：cross-track error（到路線折線的垂直距離）、下一個導引點、狀態判斷。

use crate::params::NavParams;
use serde::Serialize;

#[derive(Debug, Clone, Copy, PartialEq, Serialize)]
pub struct Track {
    /// 到路線的最短距離（公尺）
    pub xte_m: f32,
    /// 投影點沿路線的距離（公尺）
    pub along_m: f32,
    /// 路線總長（公尺）
    pub total_m: f32,
    /// 路線在位置的哪一側：+1 = 左側、−1 = 右側（以前進方向看）
    pub side: f32,
}

/// 點到折線的 cross-track error。path 為 [x, y, (z)]，至少 2 點。
pub fn cross_track(path: &[[f32; 3]], p: (f32, f32)) -> Track {
    let mut best = Track {
        xte_m: f32::INFINITY,
        along_m: 0.0,
        total_m: 0.0,
        side: 0.0,
    };
    let mut acc = 0.0f32;
    for w in path.windows(2) {
        let (a, b) = (w[0], w[1]);
        let (dx, dy) = (b[0] - a[0], b[1] - a[1]);
        let len2 = dx * dx + dy * dy;
        let len = len2.sqrt();
        let t = if len2 > 0.0 {
            (((p.0 - a[0]) * dx + (p.1 - a[1]) * dy) / len2).clamp(0.0, 1.0)
        } else {
            0.0
        };
        let (qx, qy) = (a[0] + dx * t, a[1] + dy * t);
        let d = ((p.0 - qx).powi(2) + (p.1 - qy).powi(2)).sqrt();
        if d < best.xte_m {
            let cross = dx * (p.1 - a[1]) - dy * (p.0 - a[0]);
            best = Track {
                xte_m: d,
                along_m: acc + len * t,
                total_m: 0.0,
                side: cross.signum(),
            };
        }
        acc += len;
    }
    best.total_m = acc;
    best
}

/// 沿路線距離 d 處的點。
pub fn point_along(path: &[[f32; 3]], d: f32) -> [f32; 2] {
    let mut acc = 0.0f32;
    for w in path.windows(2) {
        let (a, b) = (w[0], w[1]);
        let len = ((b[0] - a[0]).powi(2) + (b[1] - a[1]).powi(2)).sqrt();
        if acc + len >= d && len > 0.0 {
            let t = ((d - acc) / len).clamp(0.0, 1.0);
            return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
        }
        acc += len;
    }
    let l = path.last().unwrap();
    [l[0], l[1]]
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum RouteStatus {
    OnRoute,
    OffRoute,
    Replan,
}

/// 偏離路線判斷：
/// - 偏離 > `offroute_replan_m` → 重規劃
/// - 已偏離（> `offroute_warn_m`）且離危險區 < `hazard_buffer_m` → 重規劃
/// - 偏離 > `offroute_warn_m` 且 > 2σ（確定不是定位誤差造成）→ 警告
///
/// 註：危險緩衝條件只在「已偏離」時生效。science 路線本身就會經過離危險區 2 m 的地方，
/// 若在路線上也觸發會一直重規劃。
pub fn assess(
    xte_m: f32,
    sigma_m: f32,
    clearance_m: f32,
    nav: &NavParams,
) -> (RouteStatus, &'static str) {
    if xte_m > nav.offroute_replan_m {
        return (RouteStatus::Replan, "far_off_route");
    }
    let off = xte_m > nav.offroute_warn_m;
    if off && clearance_m < nav.hazard_buffer_m {
        return (RouteStatus::Replan, "off_route_near_hazard");
    }
    if off && xte_m > 2.0 * sigma_m {
        return (RouteStatus::OffRoute, "off_route");
    }
    (RouteStatus::OnRoute, "on_route")
}

#[cfg(test)]
mod tests {
    use super::*;

    fn path() -> Vec<[f32; 3]> {
        vec![[0.0, 0.0, 0.0], [100.0, 0.0, 0.0], [100.0, 100.0, 0.0]]
    }

    #[test]
    fn xte_and_along() {
        let t = cross_track(&path(), (50.0, 7.0));
        assert!((t.xte_m - 7.0).abs() < 1e-4);
        assert!((t.along_m - 50.0).abs() < 1e-4);
        assert_eq!(t.total_m, 200.0);
        assert_eq!(t.side, 1.0); // 前進方向左側（北）
        let t = cross_track(&path(), (50.0, -7.0));
        assert_eq!(t.side, -1.0);
        let t = cross_track(&path(), (103.0, 60.0));
        assert!((t.xte_m - 3.0).abs() < 1e-4 && (t.along_m - 160.0).abs() < 1e-4);
    }

    #[test]
    fn point_along_works() {
        assert_eq!(point_along(&path(), 150.0), [100.0, 50.0]);
        assert_eq!(point_along(&path(), 999.0), [100.0, 100.0]);
    }

    #[test]
    fn status_rules() {
        let nav = NavParams::default();
        // 沿路線：不警告
        assert_eq!(assess(3.0, 2.0, 50.0, &nav).0, RouteStatus::OnRoute);
        // 偏 20 m、定位很準：警告
        assert_eq!(assess(20.0, 2.0, 50.0, &nav).0, RouteStatus::OffRoute);
        // 偏 20 m 但定位不確定度 15 m：可能只是誤差，不警告
        assert_eq!(assess(20.0, 15.0, 50.0, &nav).0, RouteStatus::OnRoute);
        // 偏 40 m：重規劃
        assert_eq!(assess(40.0, 2.0, 50.0, &nav).0, RouteStatus::Replan);
        // 偏 20 m 且靠近危險區：重規劃
        assert_eq!(assess(20.0, 2.0, 5.0, &nav).0, RouteStatus::Replan);
        // 在路線上、靠近危險區（science 路線常態）：不重規劃
        assert_eq!(assess(2.0, 2.0, 2.0, &nav).0, RouteStatus::OnRoute);
    }
}
